   "id": "zbf807993",
   "sez": "medicina",
   "titolo": "Foschia nel Sud-est asiatico: Singapore aiuta a pagare le cure",
   "orig": "Asia's richest country offers haze treatment subsidies as air quality deteriorates",
   "lead": "L'aria nel Sud-est asiatico sta peggiorando a causa della foschia e Singapore corre ai ripari. Da lunedì il governo attiverà sussidi medici legati all'inquinamento, che limitano a 10 dollari di Singapore (7,82 dollari statunitensi) il costo delle cure per i pazienti che ne hanno diritto. In Malesia, a Kuching e Miri, la qualità dell'aria è migliorata ma resta a livello moderato. Domenica 11 ottobre a Metro Cebu, nelle Filippine, l'aria ha invece raggiunto il livello «molto malsano».",
   "more": [
    "La foschia che colpisce periodicamente il Sud-est asiatico è causata soprattutto dagli incendi di foreste e torbiere, usati spesso per liberare terreni agricoli. Il fumo viaggia per centinaia di chilometri e oltrepassa i confini, causando problemi respiratori."
   ],
