   "id": "zdb588a93",
   "sez": "economia",
   "titolo": "Rogoff: gli Stati Uniti verso una crisi del debito",
   "orig": "La inminente crisis de deuda en Estados Unidos",
   "lead": "In un commento pubblicato da Criterio.hn, l'economista Kenneth Rogoff mette in guardia sulla situazione dei conti pubblici degli Stati Uniti. La paragona a un treno lanciato a tutta velocità verso una crisi del debito, ormai vicina. Nelle stesse ore altre testate parlano degli Stati Uniti per motivi diversi. Il portoghese Público riferisce di un attacco americano contro una nave commerciale partita da un porto iraniano nel Golfo di Oman. Il venezuelano El Nacional racconta invece la difesa di Cristoforo Colombo da parte di Donald Trump alla Casa Bianca.",
   "more": [
    "Kenneth Rogoff è un economista dell'Università di Harvard ed è stato capo economista del Fondo monetario internazionale. È noto soprattutto per i suoi studi sulle crisi finanziarie e sul debito pubblico."
   ],
