   "id": "zd9780356",
   "sez": "musica",
   "titolo": "Ella Langley annulla un concerto a Tulsa per una minaccia di sicurezza",
   "orig": "US country music star Ella Langley cancels show due to 'security threat'",
   "lead": "La cantante country statunitense Ella Langley ha annullato un concerto al BOK Center di Tulsa, in Oklahoma, a causa di una «minaccia alla sicurezza». L'allarme è scattato dopo una telefonata che annunciava un possibile attacco, con sparatorie ed esplosioni. La polizia ha controllato la struttura due volte e non ha trovato minacce concrete, ma lo spettacolo è stato comunque cancellato. Sul caso indaga anche l'FBI.",
   "more": [
    "Ella Langley è una cantautrice country originaria dell'Alabama che negli ultimi anni ha avuto grande successo negli Stati Uniti. Il BOK Center è il principale palazzetto di Tulsa e ospita concerti ed eventi sportivi."
   ],
