   "id": "z88576e89",
   "sez": "economia",
   "titolo": "Il Tagikistan tratta sul carburante con gli Stati Uniti dopo le importazioni dall'Iran",
   "orig": "Tajikistan Holds Fuel Talks With U.S. After Starting Imports From Iran",
   "lead": "Il Tagikistan ha parlato di forniture di carburante con gli Stati Uniti, dopo aver cominciato a importare prodotti petroliferi dall'Iran. Le testate locali raccontano anche altri dati sulle importazioni del Paese. La Bielorussia è diventata il primo fornitore di carne, con un aumento delle importazioni del 60% e più di un quarto del totale. Il Tagikistan ha inoltre comprato oli vegetali per quasi 99 milioni di dollari, perché la produzione interna copre solo il 21% del fabbisogno.",
   "more": [
    "Il Tagikistan è un Paese montuoso dell'Asia centrale, senza sbocco sul mare, ed è tra i più poveri della regione. Dipende molto dalle importazioni di carburante e cibo e dalle rimesse dei suoi lavoratori all'estero."
   ],
