   "sez": "musica",
   "titolo": "Rosalía al Saturday Night Live: Reliquia sulle punte e Magnolias sotto la pioggia",
   "orig": "Shane Gillis & Rosalía on ‘SNL’: Here’s Where to Watch ‘Saturday Night Live’ Online for Free",
   "lead": "La cantautrice spagnola Rosalía è stata l'ospite musicale del Saturday Night Live di sabato 10 ottobre, puntata condotta dal comico Shane Gillis. Ha proposto due esibizioni dal forte impatto teatrale, entrambe tratte dal suo apprezzato album del 2025, «Lux». Ha cantato «Reliquia» danzando sulle punte e «Magnolias» sotto una pioggia scenografica. Billboard ha spiegato come seguire la puntata in streaming. Intanto, nella versione britannica del programma, la cantante anglo-colombiana Sasha Keable ha eseguito «Options» e «Why» accanto al conduttore Danny Dyer.",
   "more": [
    "Il Saturday Night Live è uno storico programma comico della televisione statunitense, trasmesso in diretta da New York. Ogni puntata ha un conduttore diverso e un ospite musicale. Rosalía è una delle artiste spagnole più note a livello internazionale e unisce flamenco, pop e sonorità urbane."
   ],
