   "titolo": "Fitch conferma il rating BB del gruppo minerario uzbeko NGMK, outlook positivo",
   "orig": "Fitch Affirms NGMK’s BB Rating with Positive Outlook",
   "lead": "L'agenzia di rating Fitch ha confermato il giudizio BB della Navoi Mining and Metallurgical Company, il gruppo minerario e metallurgico uzbeko noto con la sigla NGMK, e ha mantenuto l'outlook positivo. A sostegno della valutazione, l'agenzia cita i bassi costi di produzione della società, la sua elevata redditività e il sostegno dello Stato. Lo riferisce UzDaily.",
   "more": [
    "I rating delle agenzie come Fitch misurano l'affidabilità di un emittente nel ripagare i debiti. Il livello BB rientra nella fascia speculativa. Un outlook positivo segnala la possibilità di un miglioramento futuro del giudizio."
   ],
