   "titolo": "Truppe eritree avvistate nel Tigrè, cresce il timore di una guerra regionale",
   "orig": "Eritrean troops seen in Ethiopia’s Tigray as fears of wider conflict grow",
   "lead": "Mercoledì soldati eritrei hanno attraversato Adigrat, città nel nord dell'Etiopia. A riferirlo a Reuters sono stati due testimoni. L'avvistamento arriva pochi giorni dopo la rottura dei rapporti diplomatici tra i due Paesi del Corno d'Africa e alimenta il timore di un conflitto aperto. Sarebbe la prima conferma della presenza eritrea in territorio etiope durante questa crisi. Una fonte di sicurezza straniera citata da AFP stima tra 5.000 e 8.000 i militari eritrei presenti nella regione del Tigrè.",
   "more": [
    "Etiopia ed Eritrea condividono un lungo confine e una storia di conflitti, compresa una guerra sanguinosa a cavallo tra gli anni Novanta e Duemila. Il Tigrè è la regione più settentrionale dell'Etiopia, confinante con l'Eritrea, ed è stato teatro di una grave guerra civile."
   ],
