   "titolo": "Burundi, la sesta giornata della Primus Ligue si gioca su più campi",
   "orig": "Primus Ligue, 6e journée — Le championnat se déploie",
   "lead": "La sesta giornata della Primus Ligue, il campionato di calcio del Burundi, si giocherà regolarmente nonostante l'indisponibilità dello stadio Urukundo. L'impianto infatti non può essere usato nei giorni feriali, ma solo la domenica. Invece di annullare le partite, la commissione organizzatrice ha deciso di distribuirle su più impianti. Le nuove disposizioni sono contenute nella circolare FFB/COC/065/2026, pubblicata il 7 ottobre a Bujumbura dalla Federazione calcistica del Burundi. Lo riferisce Iwacu.",
   "more": [
    "Il Burundi è un piccolo Paese dell'Africa orientale, nella regione dei Grandi Laghi. La Primus Ligue è il massimo campionato di calcio nazionale e prende il nome dal suo sponsor."
   ],
