   "id": "zef62bb44",
   "sez": "cultura",
   "titolo": "Uruguay, Rocha dichiara il suo modo di parlare «patrimonio immateriale»",
   "orig": "Rocha declaró \"patrimonio inmaterial\" su lenguaje; creará un registro de palabras y refranes y buscará el reconocimiento a nivel nacional",
   "lead": "Il dipartimento uruguaiano di Rocha ha dichiarato «patrimonio immateriale» il proprio linguaggio tradizionale. L'amministrazione creerà un registro di parole e modi di dire locali e chiederà un riconoscimento anche a livello nazionale. Tra i termini tipici della zona ci sono «lambucear», «grela», «chafandín», «macuín», «zaparrastroso» e «cartapacio». Un'altra particolarità di Rocha è l'uso del «tú» al posto del «vos», che domina invece nel resto del Paese. Lo riferisce El Observador.",
   "more": [
    "In gran parte dell'Uruguay e dell'Argentina si usa il «voseo», cioè il pronome «vos» al posto di «tú» per dare del tu. Rocha è un dipartimento della costa orientale uruguaiana, al confine con il Brasile, noto per spiagge e aree naturali."
   ],
